// Called by header.php's switchLanguage() whenever the user changes the
// language from the header dropdown on ANY page (including this one, if the
// header happens to be present). Also called on load below.
function pageLanguageCallback(lang) {
    const t = SitemapT[lang] || SitemapT.en;
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };

    set('sm-title', t.title);
    set('sm-sub', t.sub);
    set('sm-col-main', t.colMain);
    set('sm-col-services', t.colServices);
    set('sm-col-community', t.colCommunity);
    set('sm-col-support', t.colSupport);
    set('sm-legal-title', t.legalTitle);

    set('sm-home', t.home);
    set('sm-about', t.about);
    set('sm-contact', t.contact);

    set('sm-store', t.store);
    set('sm-rental', t.rental);
    set('sm-marketprices', t.marketPrices);

    set('sm-advisory', t.advisory);
    set('sm-bazaar', t.bazaar);
    set('sm-connect', t.connect);

    set('sm-contactus', t.contactUs);
    set('sm-email', t.email);

    set('sm-privacy', t.privacy);
    set('sm-terms', t.terms);
    set('sm-return', t.returnPolicy);
    set('sm-refund', t.refundPolicy);
    set('sm-shipping', t.shippingPolicy);
    set('sm-cancellation', t.cancellationPolicy);
    set('sm-sellerterms', t.sellerTerms);
    set('sm-rentalterms', t.rentalTerms);

    set('sm-back', t.back);
}

// No language selector on this page — just pick up whatever was already
// chosen from the header (agri_lang in localStorage) and apply it here too.
document.addEventListener('DOMContentLoaded', () => {
    const savedLang = localStorage.getItem('agri_lang') || 'en';
    pageLanguageCallback(savedLang);
});
</script>

